def split_libre() -> Tuple[List[str], List[str], List[str], List[str]]:
    xt, yt, xs, ys = [], [], [], []
    for label, rows in CORPUS.items():
        for i, t in enumerate(rows):
            (xt if i < N_TRAIN else xs).append(t)
            (yt if i < N_TRAIN else ys).append(label)
    return xt, yt, xs, ys
